/**
 * MEASURED HIT SHAPES for the swinging plank and axe — generated, not written.
 *
 * The code cannot see inside a baked GLB animation, so both clips were sampled
 * offline and the moving mesh fitted with ORIENTED BOXES at each keyframe.
 * swingTraps.ts interpolates between them by how far through the clip the unit
 * is, so what kills you is a box round wherever the part actually IS.
 *
 * Regenerate with scratchpad/swing_obb_v4.py if either .glb or its clip changes.
 * Surface samples there are spaced by AREA, not a fixed count per triangle: the
 * plank is only 16 triangles, so a fixed count puts samples ~2m apart on an 8m
 * board and every check measured against them is blind to what it is checking.
 * Every number below came out of that script; none of it is hand-tuned, and
 * hand-editing a box means the shape no longer matches the model.
 *
 * WHY BOXES. Two earlier shapes were both wrong in ways players felt:
 *   - an axis-aligned box balloons as the thing inside it turns — mid-swing the
 *     plank's was 20.8 m3 around a 3.4 m3 board;
 *   - a capsule takes the widest perpendicular extent of what it wraps, so the
 *     axe head, measured at 2.69m across but only 0.24m THICK, became a 2.74m
 *     cylinder — you died a clear metre off the flat of the blade.
 * Measured against the mesh surface: 89% (plank) and 84% (axe) less lethal air
 * than the axis-aligned box round the same pose.
 *
 * HOW THE COUNTS WERE CHOSEN, both by measurement:
 *   - slices: kept subdividing while each extra slice still removed >8% of the
 *     lethal volume — 1 for the plank, 8 for the axe. One for the plank because
 *     a flat rigid board IS a box; an earlier bake read 8 as "tighter" only
 *     because its sparse sampling let slices come out EMPTY, and an empty slice
 *     is a hole in the hitbox, not a saving;
 *   - keyframes: kept inserting one wherever the interpolated shape sat
 *     furthest from the real mesh SURFACE, until that error came under 6cm.
 *     Worst remaining gap: 0.056m (plank), 0.072m (axe);
 *   - cross-section cells: each slice is also split ACROSS its width, into
 *     cells of at most 1m. The axe head is a CRESCENT, and a single box round a
 *     crescent is correctly thin but has empty corners — standing in one killed
 *     you with the blade 0.8m away. Cells hug the curve. The shaft and the
 *     whole plank are narrow enough to come out as one cell and are unchanged.
 *
 * TWO PROPERTIES THIS DATA MUST KEEP, both load-bearing at runtime:
 *   1. Every keyframe carries the same number of boxes, in the same order,
 *      ordered from the model's PIVOT outwards. Runtime lerps box i against
 *      box i; an earlier bake let the chain flip end-for-end between keyframes
 *      and lerping the axe's head into its handle put a multi-metre phantom in
 *      the middle of the swing.
 *   2. `t` ascends. capsAt-style lookup walks the list forwards and a
 *      non-monotonic list silently returns the wrong pose — which is exactly
 *      what a mis-paste of the axe's keyframes into the plank's array did.
 *
 * VERIFIED END TO END, not just as a fit. scratchpad/sim_swing.py replays the
 * shipped kill test — these keyframes, swingTraps.ts's interpolation and bridge
 * rule, hits.ts's box test — over 23,548 player positions per unit, on both
 * floors, through the clip, and measures how far the animated mesh really was
 * each time it said "kill":
 *
 *   plank: 12 kills, 0 unfair, 0 missed.
 *   axe:  229 kills, 9 unfair (3.9%), median 0.69m, worst 0.87m; 0 missed.
 *
 * "Unfair" means the mesh was over 0.6m from the player's capsule — so the axe's
 * remaining 9 are a visible gap of about 30cm past the player's own body radius,
 * and they are all the same thing: the head is a CRESCENT, so even a 0.68 x 0.84
 * x 0.20m cell has an empty corner. Halving the cell width would shave it again
 * at roughly double the data. "Missed" is the opposite failure — mesh through
 * the player, no kill — and there are none.
 *
 * Sampled in the MODEL's own space. swingTraps.ts rotates and scales these by
 * the unit's placed Transform, which matters: pblade2.glb_2 is placed at 180
 * degrees about Y.
 */

import { Vector3 } from '@dcl/sdk/math'

/** One oriented box of the moving part, in model space. */
export interface SwingBox {
  /** Box centre. */
  c: Vector3
  /** Unit axis along the part's own length. */
  u: Vector3
  /** Unit axis across it, perpendicular to `u`. */
  w: Vector3
  /** Half-extents along `u`, `w`, and `u` x `w` respectively. */
  h: Vector3
}

export interface SwingKeyframe {
  /** Seconds into the clip. Must ascend across the array. */
  t: number
  boxes: SwingBox[]
}

export interface SwingTrapModel {
  /**
   * EVERY clip the unit needs, not just the visible one. fplank ships two:
   * 'TemplateHN.011Action.001' drives the visible board and
   * 'TemplateHN.011Action' drives fplank_collider, and BOTH travel the same
   * 5.07m. Playing only the first would swing the board down while leaving its
   * collider up in the rest position — which would break the plank as a bridge.
   */
  clips: string[]
  /** Seconds; the full authored cycle. */
  duration: number
  /**
   * Only kill when the part comes down onto the player from above.
   *
   * The plank is a drawbridge: its underside is lethal, but once it is down you
   * are meant to walk along it to the second floor. Without this it would kill
   * the moment you stepped onto the thing it just became.
   */
  killFromBelowOnly: boolean
  /** Shown on the death screen, and after "Killed by:" on the defeat screen. */
  deathCause: string
  /**
   * Fraction of the baked box size that is actually lethal, applied to every
   * half-extent about the box centre. 1 = the boxes as measured.
   *
   * PER MODEL, not global, because the two parts are asked to do opposite
   * jobs. The axe is a pure hazard, so trimming it only ever costs a grab.
   * The plank is a BRIDGE you are meant to walk along, and its boxes are the
   * thing the drawbridge rule reasons about — shrinking it is how you fall
   * through the floor you are standing on.
   */
  extentShrink: number
  /**
   * Clip playback rate. 1 = as authored.
   *
   * Applied to the Animator AND to the elapsed clock that drives the hit boxes,
   * so the volume and the visible part stay in step — changing one without the
   * other is how a hit box ends up leading or trailing what you can see.
   */
  playbackSpeed: number
  keyframes: SwingKeyframe[]
}

