/**
 * Units ADOPTED from Creator Hub — entity name paired with its baked shape.
 *
 * The blades are back on this list. They were briefly spawned from code
 * (SWING_TRAP_PLACEMENTS in config.ts, now deleted) because pblade2.glb's
 * origin sat 5.7m from the blade, which made the editor gizmo useless and the
 * placement impossible to trust. blade.glb fixed that — its origin is on the
 * pivot — so the editor is the right place to position them again, and this is
 * the one source of truth.
 *
 * Adoption reads the entity's live world transform every frame (followEntity in
 * swingTraps.ts), so moving one in Creator Hub moves its kill volume with it.
 */
export const SWING_TRAP_UNITS: { name: string; model: SwingTrapModel }[] = [
  { name: 'fplank.glb', model: SWING_TRAP_FPLANK },
  { name: 'fplank.glb_2', model: SWING_TRAP_FPLANK },
  { name: 'fplank.glb_3', model: SWING_TRAP_FPLANK },
  { name: 'fplank.glb_4', model: SWING_TRAP_FPLANK },
  { name: 'blade.glb', model: SWING_TRAP_PBLADE },
  { name: 'blade.glb_2', model: SWING_TRAP_PBLADE }
]
